def test_insert_and_update_counts():
    c = fresh()
    add_contact(c, "a@b.com", "Old")
    res = import_contacts(c, [
        {"email": "  New@X.com ", "name": " Neo "},
        {"email": "a@b.com", "name": "Old"},
    ])
    assert res == {"inserted": 1, "updated": 1}
    assert list_contacts(c) == [("a@b.com", "Old"), ("new@x.com", "Neo")]

def test_update_changes_name():
    c = fresh()
    add_contact(c, "a@b.com", "Old")
    assert import_contacts(c, [{"email": "A@B.com", "name": "New"}]) == {"inserted": 0, "updated": 1}
    assert list_contacts(c) == [("a@b.com", "New")]

def test_empty_batch():
    c = fresh()
    assert import_contacts(c, []) == {"inserted": 0, "updated": 0}

@pytest.mark.parametrize("row", [
    "x",
    {"email": "a@b.com"},
    {"email": "a@b.com", "name": "A", "extra": 1},
    {"email": "a@@b.com", "name": "A"},
    {"email": "a@b", "name": "A"} if False else {"email": "ab.com", "name": "A"},
    {"email": "@b.com", "name": "A"},
    {"email": "a@", "name": "A"},
    {"email": "a b@c.com", "name": "A"},
    {"email": "a@b.com", "name": "   "},
    {"email": 1, "name": "A"},
])
def test_invalid_rows_rejected_and_nothing_written(row):
    c = fresh()
    add_contact(c, "keep@x.com", "Keep")
    with pytest.raises(ValueError):
        import_contacts(c, [{"email": "ok@x.com", "name": "Ok"}, row])
    assert list_contacts(c) == [("keep@x.com", "Keep")]

def test_duplicate_normalized_emails_rejected():
    c = fresh()
    with pytest.raises(ValueError):
        import_contacts(c, [{"email": "a@b.com", "name": "1"}, {"email": " A@B.COM", "name": "2"}])
    assert list_contacts(c) == []

def test_db_failure_rolls_back():
    c = fresh()
    add_contact(c, "keep@x.com", "Keep")
    c.execute("CREATE TRIGGER boom BEFORE INSERT ON contacts WHEN NEW.email = 'bad@x.com' BEGIN SELECT RAISE(ABORT, 'boom'); END")
    c.commit()
    with pytest.raises(sqlite3.DatabaseError):
        import_contacts(c, [{"email": "good@x.com", "name": "G"}, {"email": "bad@x.com", "name": "B"}])
    assert list_contacts(c) == [("keep@x.com", "Keep")]

def test_handle_import_envelope():
    c = fresh()
    assert handle_import(c, {"contacts": [{"email": "a@b.com", "name": "A"}]}) == {"inserted": 1, "updated": 0}
    for bad in [[], {}, {"contacts": [], "x": 1}, {"rows": []}, {"contacts": "nope"}, None]:
        with pytest.raises(ValueError):
            handle_import(c, bad)
    assert handle_add(c, {"email": "z@z.com", "name": "Z"}) == {"ok": True}
